31	TheoryInferenceManager::TheoryInferenceManager(Env& env,
32	                                               Theory& t,
33	                                               TheoryState& state,
34	                                               const std::string& statsName,
35	                                               bool cacheLemmas)
36	    : EnvObj(env),
37	      d_theory(t),
38	      d_theoryState(state),
39	      d_out(t.getOutputChannel()),
40	      d_ee(nullptr),
41	      d_decManager(nullptr),
42	      d_pfee(nullptr),
43	      d_cacheLemmas(cacheLemmas),
44	      d_keep(context()),
45	      d_lemmasSent(userContext()),
46	      d_numConflicts(0),
47	      d_numCurrentLemmas(0),
48	      d_numCurrentFacts(0),
49	      d_conflictIdStats(statisticsRegistry().registerHistogram<InferenceId>(
50	          statsName + "inferencesConflict")),
51	      d_factIdStats(statisticsRegistry().registerHistogram<InferenceId>(
52	          statsName + "inferencesFact")),
53	      d_lemmaIdStats(statisticsRegistry().registerHistogram<InferenceId>(
54	          statsName + "inferencesLemma"))
55	{
56	  // don't add true lemma
57	  Node truen = nodeManager()->mkConst(true);
58	  d_lemmasSent.insert(truen);
59	
60	  if (isProofEnabled())
61	  {
62	    context::UserContext* u = userContext();
63	    d_defaultPg.reset(
64	        new EagerProofGenerator(env, u, statsName + "EagerProofGenerator"));
65	  }
66	}
