70	void TheoryInferenceManager::setEqualityEngine(eq::EqualityEngine* ee)
71	{
72	  d_ee = ee;
73	  // if proofs are enabled, also make a proof equality engine to wrap ee
74	  // if it is non-null. If its proof equality engine has already been assigned,
75	  // use it. This is to ensure that all theories use the same proof equality
76	  // engine when in ee-mode=central.
77	  if (isProofEnabled() && d_ee != nullptr)
78	  {
79	    d_pfee = d_ee->getProofEqualityEngine();
80	    if (d_pfee == nullptr)
81	    {
82	      d_pfeeAlloc = std::make_unique<eq::ProofEqEngine>(d_env, *d_ee);
83	      d_pfee = d_pfeeAlloc.get();
84	      d_ee->setProofEqualityEngine(d_pfee);
85	    }
86	  }
87	}
