196	bool TheoryInferenceManager::propagateLit(TNode lit)
197	{
198	  // If already in conflict, no more propagation
199	  if (d_theoryState.isInConflict())
200	  {
201	    return false;
202	  }
203	  // Propagate out
204	  bool ok = d_out.propagate(lit);
205	  if (!ok)
206	  {
207	    d_theoryState.notifyInConflict();
208	  }
209	  return ok;
210	}
