212	TrustNode TheoryInferenceManager::explainLit(TNode lit)
213	{
214	  if (d_pfee != nullptr)
215	  {
216	    return d_pfee->explain(lit);
217	  }
218	  if (d_ee != nullptr)
219	  {
220	    Node exp = d_ee->mkExplainLit(lit);
221	    return TrustNode::mkTrustPropExp(lit, exp, nullptr);
222	  }
223	  Unimplemented() << "Inference manager for " << d_theory.getId()
224	                  << " was asked to explain a propagation but doesn't have an "
225	                     "equality engine or implement the "
226	                     "TheoryInferenceManager::explainLit interface!";
