252	bool TheoryInferenceManager::trustedLemma(const TrustNode& tlem,
253	                                          InferenceId id,
254	                                          LemmaProperty p)
255	{
256	  // if the policy says to cache lemmas, check the cache and return false if
257	  // we are a duplicate
258	  if (d_cacheLemmas && !isLemmaPropertyLocal(p))
259	  {
260	    if (!cacheLemma(tlem.getNode(), p))
261	    {
262	      return false;
263	    }
264	  }
265	  Assert(id != InferenceId::UNKNOWN)
266	      << "Must provide an inference id for lemma";
267	  d_lemmaIdStats << id;
268	  resourceManager()->spendResource(id);
269	  Trace("im") << "(lemma " << id << " " << tlem.getProven() << ")" << std::endl;
270	  // shouldn't send trivially true or false lemmas
271	  Assert(!rewrite(tlem.getProven()).isConst());
272	  d_numCurrentLemmas++;
273	  d_out.trustedLemma(tlem, id, p);
274	  return true;
275	}
