383	bool TheoryInferenceManager::processInternalFact(TNode atom,
384	                                                 bool pol,
385	                                                 InferenceId iid,
386	                                                 ProofRule id,
387	                                                 const std::vector<Node>& exp,
388	                                                 const std::vector<Node>& args,
389	                                                 ProofGenerator* pg)
390	{
391	  Assert(iid != InferenceId::UNKNOWN)
392	      << "Must provide an inference id for fact";
393	  d_factIdStats << iid;
394	  resourceManager()->spendResource(iid);
395	  // make the node corresponding to the explanation
396	  Node expn = nodeManager()->mkAnd(exp);
397	  Trace("im") << "(fact " << iid << " " << (pol ? Node(atom) : atom.notNode())
398	              << " " << expn << ")" << std::endl;
399	  // call the pre-notify fact method with preReg = false, isInternal = true
400	  if (d_theory.preNotifyFact(atom, pol, expn, false, true))
401	  {
402	    // Handled in a theory-specific way that doesn't require equality engine,
403	    // notice we return true, indicating that the fact was processed.
404	    return true;
405	  }
406	  Assert(d_ee != nullptr);
407	  Trace("infer-manager") << "TheoryInferenceManager::assertInternalFact: "
408	                         << (pol ? Node(atom) : atom.notNode()) << " from "
409	                         << expn << " / " << iid << " " << id << std::endl;
410	  if (Configuration::isAssertionBuild())
411	  {
412	    // check that all facts hold in the equality engine, to ensure that we
413	    // aren't processing a stale fact
414	    std::vector<Node> expc = exp;
415	    for (size_t i = 0; i < expc.size(); i++)
416	    {
417	      Node e = expc[i];
418	      bool epol = e.getKind() != Kind::NOT;
419	      Node eatom = epol ? e : e[0];
420	      Trace("infer-manager")
421	          << "...check " << eatom << " " << epol << std::endl;
422	      if (eatom.getKind() == Kind::AND)
423	      {
424	        Assert(epol);
425	        for (const Node& ea : eatom)
426	        {
427	          expc.push_back(ea);
428	        }
429	        continue;
430	      }
431	      else if (eatom.getKind() == Kind::EQUAL)
432	      {
433	        Assert(d_ee->hasTerm(eatom[0]));
434	        Assert(d_ee->hasTerm(eatom[1]));
435	        Assert(!epol || d_ee->areEqual(eatom[0], eatom[1]));
436	        Assert(epol || d_ee->areDisequal(eatom[0], eatom[1], false));
437	      }
438	      else
439	      {
440	        Assert(d_ee->hasTerm(eatom));
441	        Assert(d_ee->areEqual(eatom, nodeManager()->mkConst(epol)));
442	      }
443	    }
444	  }
445	  d_numCurrentFacts++;
446	  // Now, assert the fact. How to do so depends on whether proofs are enabled.
447	  bool ret = false;
448	  if (d_pfee == nullptr)
449	  {
450	    Trace("infer-manager") << "...assert without proofs..." << std::endl;
451	    if (atom.getKind() == Kind::EQUAL)
452	    {
453	      ret = d_ee->assertEquality(atom, pol, expn);
454	    }
455	    else
456	    {
457	      ret = d_ee->assertPredicate(atom, pol, expn);
458	    }
459	    // Must reference count the equality and its explanation, which is not done
460	    // by the equality engine. Notice that we do *not* need to do this for
461	    // external assertions, which enter as facts in theory check. This is also
462	    // not done if we are asserting to the proof equality engine, which does
463	    // this caching itself within ProofEqEngine::assertFact.
464	    d_keep.insert(atom);
465	    d_keep.insert(expn);
466	  }
467	  else
468	  {
469	    Assert(id != ProofRule::UNKNOWN);
470	    Trace("infer-manager") << "...assert with proofs..." << std::endl;
471	    // Note that we reconstruct the original literal lit here, since both the
472	    // original literal is needed for bookkeeping proofs. It is possible to
473	    // optimize this so that a few less nodes are created, but at the cost
474	    // of a more verbose interface to proof equality engine.
475	    Node lit = pol ? Node(atom) : atom.notNode();
476	    if (pg != nullptr)
477	    {
478	      // use the proof generator interface
479	      ret = d_pfee->assertFact(lit, expn, pg);
480	    }
481	    else
482	    {
483	      // use the explict proof step interface
484	      ret = d_pfee->assertFact(lit, id, expn, args);
485	    }
486	  }
487	  // call the notify fact method with isInternal = true
488	  d_theory.notifyFact(atom, pol, expn, true);
489	  Trace("infer-manager")
490	      << "TheoryInferenceManager::finished assertInternalFact, ret=" << ret
491	      << std::endl;
492	  return ret;
493	}
