495	void TheoryInferenceManager::explain(TNode n, std::vector<TNode>& assumptions)
496	{
497	  if (n.getKind() == Kind::AND)
498	  {
499	    for (const Node& nc : n)
500	    {
501	      d_ee->explainLit(nc, assumptions);
502	    }
503	  }
504	  else
505	  {
506	    d_ee->explainLit(n, assumptions);
507	  }
508	}
