517	Node TheoryInferenceManager::mkExplainPartial(
518	    const std::vector<Node>& exp, const std::vector<Node>& noExplain)
519	{
520	  std::vector<TNode> assumps;
521	  for (const Node& e : exp)
522	  {
523	    if (std::find(noExplain.begin(), noExplain.end(), e) != noExplain.end())
524	    {
525	      if (std::find(assumps.begin(), assumps.end(), e) == assumps.end())
526	      {
527	        // a non-explained literal
528	        assumps.push_back(e);
529	      }
530	      continue;
531	    }
532	    // otherwise, explain it
533	    explain(e, assumps);
534	  }
535	  return nodeManager()->mkAnd(assumps);
536	}
