49	bool InferenceManagerBuffered::addPendingLemma(Node lem,
50	                                               InferenceId id,
51	                                               LemmaProperty p,
52	                                               ProofGenerator* pg,
53	                                               bool checkCache)
54	{
55	  if (checkCache)
56	  {
57	    // check if it is unique up to rewriting
58	    Node lemr = rewrite(lem);
59	    if (hasCachedLemma(lemr, p))
60	    {
61	      return false;
62	    }
63	  }
64	  // make the simple theory lemma
